import{_ as r,o as d,c as o,a1 as n}from"./chunks/framework.hVCBBfmZ.js";const p=JSON.parse('{"title":"App 的 React Native 落地评估","description":"","frontmatter":{"title":"App 的 React Native 落地评估","date":"2026-09-21T08:28:43.000Z","recommend":true},"headers":[],"relativePath":"posts/rn.md","filePath":"posts/rn.md"}'),e={name:"posts/rn.md"};function s(a,t,g,h,l,i){return d(),o("div",null,[...t[0]||(t[0]=[n(`<blockquote><p><strong>写在前面</strong>：本文由一份内部技术调研报告脱敏改写，当时的论证前提是&quot;把热更新与灰度下发作为首要目标&quot;。就个人观点补充一句：如果业务诉求主要是<strong>内容、活动、开关这类配置动态化</strong>，用服务端下发 + 配置化 UI（甚至沿用现有 H5 / 小程序容器）就能解决，成本远低于引入 RN；RN 真正的价值只在<strong>代码级缺陷的快速修复</strong>与<strong>新功能 / 新页面的小流量灰度</strong>这两类场景。此外 RN 的完整落地成本并不低（OTA 通道、组件库、原生桥接、版本升级回归、监控），页面体验在复杂动画与长列表场景仍需额外优化，并不天然等于原生。<strong>是否值得引入，取决于你真正的诉求是什么——请先确认这一点，再参考本文。</strong></p></blockquote><blockquote><p>本文从一个真实的三端（iOS / Android / HarmonyOS NEXT）业务需求出发，系统评估引入 React Native 的可行性、热更新（OTA）的落地方式与安全边界，以及它对测试、发布流程与长期维护的影响。文中涉及的人天与费用均为<strong>公开报价或通用参考估算</strong>，不代表任何具体团队的实际情况，请以自身评估结果为准。</p></blockquote><h2 id="_1-背景与结论" tabindex="-1">1. 背景与结论 <a class="header-anchor" href="#_1-背景与结论" aria-label="Permalink to &quot;1. 背景与结论&quot;">​</a></h2><h3 id="_1-1-现状与诉求" tabindex="-1">1.1 现状与诉求 <a class="header-anchor" href="#_1-1-现状与诉求" aria-label="Permalink to &quot;1.1 现状与诉求&quot;">​</a></h3><ul><li>iOS、Android 两端均为<strong>原生开发</strong>，<strong>Kotlin Multiplatform（KMP）</strong> 共享部分逻辑层代码；HarmonyOS NEXT 为明确的第三端。</li><li>KMP 解决&quot;逻辑层复用&quot;，<strong>不解决动态化</strong>——产物为原生二进制，改动仍需走商店审核。</li><li>当前第一诉求是<strong>线上热更新</strong>：线上问题与运营内容不依赖发版节奏即可生效。</li></ul><h3 id="_1-2-结论" tabindex="-1">1.2 结论 <a class="header-anchor" href="#_1-2-结论" aria-label="Permalink to &quot;1.2 结论&quot;">​</a></h3><p><strong>采用 React Native（RN），以&quot;原生主壳 + 统一 RN 容器&quot;的混合架构接入，现有原生工程不推翻、主链路不动。</strong></p><p>决定性的只有一条：<strong>RN 是唯一能同时覆盖 iOS、Android、HarmonyOS NEXT 三端、且具备合规热更新能力的方案。</strong> 业务代码以 JS Bundle 形式运行在 App 内置 JS 引擎中，可不重新提交商店审核即更新；Flutter 的 AOT 产物与 KMP 的二进制产物都不具备此能力。二者在&quot;热更新&quot;维度上为 0 分，而这正是当前第一诉求。</p><p><strong>这里的&quot;热更新&quot;指两类能力</strong>：① <strong>线上问题快速修复</strong>；② <strong>新功能 / 新活动的小流量灰度发布</strong>。后者（灰度）是本文假设的主要场景，价值不亚于快速修复——它把&quot;上线风险&quot;从一次性全量变成可控放量。</p><p>次之的理由：RN 三端均有可用且持续跟版的实现（鸿蒙侧为 <code>ohos_react_native</code>，即 RNOH），对现有工程侵入性低，可逐页替换。</p><p><strong>OTA（热更新通道）落地方式：倾向自建</strong>（服务端 + 自有 CDN + 自建加解密验签），一次性约 <strong>60–100 人天</strong>；若一期排期不允许，可<strong>先用国内三方服务 Pushy 过渡</strong>（2–5 人天、约 ¥792/年起，已支持鸿蒙三端），后续基于其开源实现迁移自建，<strong>不会被厂商锁死</strong>。</p><p>选择自建的核心原因：<strong>热更新的主要用途之一是灰度发布</strong>，而灰度策略、版本矩阵、密钥体系必须掌握在我们自己手里（详见第 3.4 节）：</p><ol><li><strong>灰度维度要自定义</strong>——按版本、渠道、设备分桶、人群定向，并与自家 AB 实验与埋点打通；通用服务的灰度能力是固定的，难以满足&quot;按会员等级/城市/门店放量&quot;这类诉求。</li><li><strong>版本矩阵是安全底线</strong>——Bundle 与二进制的兼容约束、错配拒绝、强制回滚，必须与自有发版流程强绑定，无法外包。</li><li><strong>密钥与设备可信要接自家风控</strong>。</li><li><strong>通道是关键基础设施</strong>——不应挂在单一供应商生命周期上（微软 App Center 已于 2025-03-31 停服)。</li><li><strong>端到端加密在原版三方 SDK 上做不到</strong>——托管（SaaS）服务端不可控；私有化部署需 fork 开源客户端自行加解密钩子并长期维护；自建则完全自由（详见第 3.4 节）。</li><li><strong>自建可避免业务代码存放在第三方</strong>——若采用托管，我们的 Bundle 与业务逻辑将保存在供应商服务器上。</li></ol><h3 id="_1-3-rn-的缺点-必须一并接受" tabindex="-1">1.3 RN 的缺点（必须一并接受） <a class="header-anchor" href="#_1-3-rn-的缺点-必须一并接受" aria-label="Permalink to &quot;1.3 RN 的缺点（必须一并接受）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>缺点</th><th>实际影响</th><th>我们的应对</th></tr></thead><tbody><tr><td>性能弱于原生，冷启动与重负载渲染差距可感知</td><td>二级页面可接受；主链路不可用 RN</td><td>首页/选座/支付保持原生（第 5 章）；具体差值以 PoC 实测为准，不引用第三方估值</td></tr><tr><td><strong>RN 运行时升级后，需要对全部 RN 页面做回归</strong>（升级动作本身不难，难的是回归范围）</td><td>每次升级带来一轮全量级测试，测试成本周期性上升；三端版本不同步还会放大</td><td>见第 6 章：升级节奏、回归策略与降本纪律</td></tr><tr><td>鸿蒙侧版本适配滞后上游，三方库存在缺口</td><td>可能推高工作量</td><td>落地前做依赖清单盘点</td></tr><tr><td>引入新技术栈与规范，短期效率下降</td><td>前 1–2 个模块会变慢</td><td>先做低频低风险模块试点</td></tr></tbody></table><p><strong>上述缺点客观存在，但在&quot;热更新&quot;这一第一诉求面前是可接受的代价——因为另两个方案在该诉求上是 0 分。</strong></p><h3 id="_1-4-上线后用什么指标证明做成了-落地与验收指标" tabindex="-1">1.4 上线后用什么指标证明做成了（落地与验收指标） <a class="header-anchor" href="#_1-4-上线后用什么指标证明做成了-落地与验收指标" aria-label="Permalink to &quot;1.4 上线后用什么指标证明做成了（落地与验收指标）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>含义</th><th>建议口径</th></tr></thead><tbody><tr><td>双端代码复用率</td><td>RN 业务代码在 iOS/Android 的复用程度</td><td>L2 层 ≥ 70%（首个试点模块实测）</td></tr><tr><td>需求交付周期</td><td>从需求到上线的平均周期</td><td>较引入前下降（基准值在试点阶段建立）</td></tr><tr><td>热更覆盖率</td><td>线上 JS 层问题中可通过热更修复的比例</td><td>以试点模块统计</td></tr><tr><td>崩溃率 / ANR 率</td><td>RN 页面 vs 原生同类页面</td><td>不高于原生同类</td></tr><tr><td>Bundle 体积</td><td>单 Bundle 与增量包大小</td><td>设预算红线，超限阻断</td></tr><tr><td>首屏耗时 / 帧率</td><td>RN 页面体验</td><td>不低于 5.2 约定的体验达标线</td></tr></tbody></table><p>以上指标的<strong>基准值在试点阶段用自有页面实测确定，不引用第三方估值</strong>。</p><hr><h2 id="_2-rn-技术底座与-2026-年版本现状" tabindex="-1">2. RN 技术底座与 2026 年版本现状 <a class="header-anchor" href="#_2-rn-技术底座与-2026-年版本现状" aria-label="Permalink to &quot;2. RN 技术底座与 2026 年版本现状&quot;">​</a></h2><h3 id="_2-1-它是怎么跑起来的" tabindex="-1">2.1 它是怎么跑起来的 <a class="header-anchor" href="#_2-1-它是怎么跑起来的" aria-label="Permalink to &quot;2.1 它是怎么跑起来的&quot;">​</a></h3><p>RN 的新架构由 <strong>JSI</strong>（JS 与 C++ 直接调用层）、<strong>Fabric</strong>（新渲染器）、<strong>TurboModules</strong>（原生能力模块，按需懒加载，TS 契约经 Codegen 生成三端绑定）组成。其中与本项目关系最直接的是 JS 引擎：</p><table tabindex="0"><thead><tr><th>组成</th><th>作用</th></tr></thead><tbody><tr><td><strong>Hermes（V1）</strong></td><td>Meta 自研移动端 JS 引擎，<strong>构建期</strong>把 JS 预编译为字节码，运行时跳过解析；它同时是第 3.3 节安全体系的第一道门</td></tr></tbody></table><p><strong>与现有工程的关系</strong>：RN 不是&quot;另一套 App&quot;，而是可嵌入的<strong>视图容器</strong>。原生侧提供页面容器（iOS <code>UIViewController</code> / Android <code>Activity</code>·<code>Fragment</code> / 鸿蒙 <code>RNApp</code>），容器内加载 RN 页面；容器之外的启动、首页、支付、选座保持原生，二者通过 TurboModules 互相调用。</p><h3 id="_2-2-版本现状与升级策略-直接影响项目排期" tabindex="-1">2.2 版本现状与升级策略（<strong>直接影响项目排期</strong>） <a class="header-anchor" href="#_2-2-版本现状与升级策略-直接影响项目排期" aria-label="Permalink to &quot;2.2 版本现状与升级策略（**直接影响项目排期**）&quot;">​</a></h3><p>RN 官方策略（reactnative.dev/releases）：每 2 个月一个次版本，<strong>只维护最近 3 个次版本系列</strong>。2026-09 现状：</p><table tabindex="0"><thead><tr><th>版本</th><th>发布日期</th><th>官方支持状态</th></tr></thead><tbody><tr><td>0.88.x</td><td>2026-10-12（计划）</td><td>Future</td></tr><tr><td><strong>0.87.x</strong></td><td>2026-08-10</td><td><strong>Active</strong></td></tr><tr><td><strong>0.86.x</strong></td><td>2026-06-09</td><td><strong>Active</strong></td></tr><tr><td>0.85.x</td><td>2026-04-06</td><td>End of Cycle</td></tr><tr><td><strong>0.84.x</strong></td><td>2026-02-09</td><td><strong>Unsupported</strong></td></tr><tr><td>0.83.x 及更早</td><td>2025-12 及更早</td><td>Unsupported</td></tr></tbody></table><p>鸿蒙侧 RNOH 版本线：主线 <strong>v0.84.3（2026-08）</strong>，并行维护 0.82 / 0.77 / 0.72 三条旧线。</p><p><strong>落地硬前置</strong>：RNOH 部分工具链与 SDK 需通过对应开发者门户申请合作伙伴 / 白名单后方可获取完整套件，建议 PoC 阶段尽早推进。</p><p><strong>必须提前决策的矛盾</strong>：RNOH 主线所在的 0.84，<strong>官方口径下已进入 Unsupported</strong>（不再有新补丁）。</p><p><strong>为什么&quot;三端 RN 版本不一致&quot;会实实在在产生成本</strong>：</p><table tabindex="0"><thead><tr><th>影响</th><th>具体表现</th></tr></thead><tbody><tr><td>同一份业务代码跑在两套运行时上</td><td>二者在渲染、手势、动画、API 行为上有差异，可能出现&quot;两端正常、鸿蒙异常&quot;，排查时无法直接归因</td></tr><tr><td>三方库适配状态不同</td><td>一个库在 iOS/Android 是最新版，鸿蒙可能只有旧版或需 <code>rntpc_*</code> 适配版本，业务代码要写平台分支</td></tr><tr><td>缺陷要分头处理</td><td>同一 Bug 可能只在一端出现，补丁分别验证；热更也要按端分别出包与灰度</td></tr><tr><td>版本矩阵与灰度更复杂</td><td>下发服务要维护多套&quot;App 版本 × Bundle 版本 × RN 版本 × 端&quot;的兼容关系，错配风险成倍上升</td></tr><tr><td>升级节奏不同步</td><td>等于长期维护两套状态，每次升级都要评估两次</td></tr></tbody></table><p><strong>建议</strong>：</p><ol><li><strong>落地前先向华为 / RNOH 社区确认 0.86（或更高）版本线的可用时间与适配范围</strong>；若可获得，三端统一 pin 在 <strong>0.86 线</strong>（Active）。</li><li>若鸿蒙短期内只能用 0.84，则三端先统一到 0.84，同时把&quot;升级到 Active 版本&quot;列入首季度硬性任务——停在 Unsupported 版本意味着安全补丁需自行处理。</li><li><strong>不要拆成两版本并行</strong>：表面是&quot;让 iOS/Android 用上最新版&quot;，实际是长期维护两套运行时，上表五项成本同时发生，<strong>总成本高于&quot;三端统一停在稍旧版本&quot;</strong>。</li></ol><hr><h2 id="_3-核心-热更新-ota" tabindex="-1">3. 核心：热更新（OTA） <a class="header-anchor" href="#_3-核心-热更新-ota" aria-label="Permalink to &quot;3. 核心：热更新（OTA）&quot;">​</a></h2><h3 id="_3-1-能带来什么-保守表述" tabindex="-1">3.1 能带来什么（保守表述） <a class="header-anchor" href="#_3-1-能带来什么-保守表述" aria-label="Permalink to &quot;3.1 能带来什么（保守表述）&quot;">​</a></h3><p><strong>热更新不是只有&quot;修 Bug&quot;——它的两大能力是&quot;快速修复&quot;与&quot;灰度发布&quot;，后者（最后一行）是本次确定的核心用途：</strong></p><table tabindex="0"><thead><tr><th>场景</th><th>现状</th><th>引入 OTA 后</th></tr></thead><tbody><tr><td>线上 RN 页面的逻辑缺陷</td><td>随版本发布，按天/周计</td><td>修复后即可下发，分钟～小时级</td></tr><tr><td>运营内容（活动、文案、权益）临时变更</td><td>无法及时处理</td><td>可定向下发、可回滚</td></tr><tr><td>双端（三端）表现不一致</td><td>分别排期</td><td>一次下发同步生效</td></tr><tr><td><strong>新功能 / 新活动的小流量灰度验证</strong></td><td>只能等发版全量上，风险集中</td><td><strong>按比例放量、看数据再全量，出问题随时回滚</strong>（本次确定的核心用途）</td></tr></tbody></table><p><strong>边界</strong>：热更新只能更新 <strong>JS 层</strong>。原生能力的新增与修改（新 SDK、新权限、原生 UI）<strong>仍必须走应用商店</strong>，这是硬性约束。</p><h3 id="_3-2-合规红线-写入开发规范" tabindex="-1">3.2 合规红线（写入开发规范） <a class="header-anchor" href="#_3-2-合规红线-写入开发规范" aria-label="Permalink to &quot;3.2 合规红线（写入开发规范）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>平台</th><th>规则要点</th></tr></thead><tbody><tr><td><strong>Apple</strong></td><td>审核指南 2.5.2 禁止下载会引入或改变 App 功能的代码；但开发者协议豁免条款（旧 §3.3.2，2025 年改版后为 §3.3.1(B)）允许**通过系统内置 WebKit / JavaScriptCore 运行的解释型代码（含 JavaScript）**下发，前提是：①不改变 App 主要用途；②不为其他代码/App 创建商店；③不绕过签名、沙盒等安全机制。2017 年 3 月苹果曾就 JSPatch 类方案群发警告要求移除——<strong>被禁原因是它把 Objective-C runtime 能力几乎无保留暴露给 JS，具备&quot;审核后任意改变 App 行为&quot;的能力，而非因为用了 JS</strong></td></tr><tr><td><strong>Android（国内商店）</strong></td><td>安卓包只在国内商店上架。国内主流商店<strong>未见针对 JS Bundle 热更新的明确禁止性条款</strong>，但需遵守：①不得借热更新绕过个人信息保护、权限与广告合规（工信部监管范围）；②不得下发或加载原生可执行代码（dex / JAR / .so）。<strong>建议按与 iOS 相同的红线执行，避免两端标准不一</strong></td></tr></tbody></table><p><strong>由此推出的红线</strong>：只下发 JS 层；不下发任何原生二进制；不用热更上线审核时未出现的功能或权限；不绕过支付与鉴权。</p><h3 id="_3-3-安全-加密与验签是必做项-不是可选项" tabindex="-1">3.3 安全：加密与验签是必做项，不是可选项 <a class="header-anchor" href="#_3-3-安全-加密与验签是必做项-不是可选项" aria-label="Permalink to &quot;3.3 安全：加密与验签是必做项，不是可选项&quot;">​</a></h3><p><strong>先纠正两个常见误解</strong>：</p><ul><li><strong>Meta 做的是&quot;Hermes 字节码预编译&quot;</strong>——构建期把 JS 编译成字节码，产物不再是明文源码，客观上形成很强的混淆效果，同时带来启动与内存收益；<strong>但字节码 ≠ 加密</strong>，社区存在针对 Hermes 字节码的反汇编工具，不足以抵御有动机的攻击者。</li><li><strong>Meta 不提供任何官方的 Bundle 加密或热更新签名产品。</strong></li></ul><p><strong>因此需要自建加密验签体系</strong>——具体做法与&quot;端到端加密只能用自建&quot;的结论详见 3.4。</p><h3 id="_3-4-ota-落地方式-自建-vs-采购" tabindex="-1">3.4 OTA 落地方式：自建 vs 采购 <a class="header-anchor" href="#_3-4-ota-落地方式-自建-vs-采购" aria-label="Permalink to &quot;3.4 OTA 落地方式：自建 vs 采购&quot;">​</a></h3><h4 id="三种方式-先把概念分清" tabindex="-1">三种方式（先把概念分清） <a class="header-anchor" href="#三种方式-先把概念分清" aria-label="Permalink to &quot;三种方式（先把概念分清）&quot;">​</a></h4><p>国内<strong>唯一同时覆盖 iOS / Android / HarmonyOS 三端的 RN 热更新服务是 Pushy</strong>（React Native 中文网，<code>react-native-update</code>）。围绕它有三种落地方式，<strong>关键区别在于&quot;服务端在谁机房&quot;和&quot;客户端是不是我们自己的&quot;</strong>：</p><table tabindex="0"><thead><tr><th>方式</th><th>服务端与 CDN</th><th>App 端</th><th>能否做自定义端到端加密</th></tr></thead><tbody><tr><td><strong>A 托管（SaaS）</strong></td><td>Pushy 的服务器与 CDN</td><td>集成 <code>react-native-update</code> SDK</td><td><strong>不能</strong></td></tr><tr><td><strong>C 私有化部署</strong></td><td><strong>服务端部署在我们自己的机器</strong>（官方提供定制版 / 私有服务器部署）</td><td><strong>仍是同一个 SDK</strong>，客户端逻辑不用我们写</td><td><strong>不能</strong></td></tr><tr><td><strong>B 完全自建</strong></td><td>我们自研</td><td>我们自研下载 / 验签 / 解密 / 回滚模块</td><td><strong>能</strong></td></tr></tbody></table><p><strong>注意</strong>：托管 ≠ 私有化部署。托管是把 bundle 传给 Pushy 的服务器；私有化部署是把它的服务端搬到我们自己的机房，但 <strong>App 里跑的仍是它的 SDK</strong>，两者在客户端能力上完全一致。</p><p><strong>关于&quot;基于开源实现自建&quot;在业内的使用情况</strong>：公开资料<strong>未见使用规模的统计数据</strong>，因此无法断言&quot;大家都在这么用&quot;。可确认的事实是——Pushy 官方提供定制版与私有服务器部署方案，且其<strong>客户端、CLI、管理界面代码开源</strong>，这意味着技术上可行、<strong>不存在被厂商锁死的风险</strong>。</p><p>它的取舍一句话：<strong>优点是服务端与数据自持、客户端逻辑现成、投入远低于完全自建；缺点是开源服务端的功能与升级保障需自行承担、客户端仍受 SDK 能力边界限制，且私有部署的费用与方案需与官方商务确认</strong>。</p><p>行业风险提示：App Center（CodePush）已于 2025-03-31 停服、CodePush Server 仓库 2025-05-20 归档——<strong>通道完全交给单一供应商存在生命周期风险</strong>。</p><h4 id="关键约束-端到端加密的边界-托管做不到-私有化要确认-自建才确定可行" tabindex="-1">关键约束：端到端加密的边界（托管做不到，私有化要确认，自建才确定可行） <a class="header-anchor" href="#关键约束-端到端加密的边界-托管做不到-私有化要确认-自建才确定可行" aria-label="Permalink to &quot;关键约束：端到端加密的边界（托管做不到，私有化要确认，自建才确定可行）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>方式</th><th>能否做端到端加密</th><th>原因</th></tr></thead><tbody><tr><td><strong>托管（SaaS）</strong></td><td><strong>做不到</strong></td><td>服务端逻辑不可控，无法让它&quot;算完明文 diff 再加密&quot;，也接不进我们的密钥体系</td></tr><tr><td><strong>私有化部署 + fork 开源客户端</strong></td><td><strong>理论上可行，但有前提</strong></td><td>前提是其服务端允许在&quot;算完明文 diff 之后&quot;再加密补丁；但 Pushy 公开开源的是客户端 / CLI / 管理界面，<strong>服务端是否可改需向官方确认</strong>；且需长期维护 fork</td></tr><tr><td><strong>完全自建</strong></td><td><strong>完全自由，唯一确定可行</strong></td><td>加密、签名、密钥体系全部自定，不依赖任何第三方可改性</td></tr></tbody></table><p>两个需要纠正的常见说法：</p><ul><li>&quot;加密会毁掉差分&quot;——<strong>不绝对</strong>。若在<strong>服务端算 diff 之前</strong>就加密 bundle，则毁掉差分；若在<strong>算完 diff 之后</strong>只加密补丁包，则不影响差分（diff 是对明文算的，加密只发生在传输层）。</li><li>&quot;SDK 没有解密钩子&quot;——<strong>原版没有，但客户端开源可改</strong>，加解密钩子技术上可行，代价是长期维护 fork。</li></ul><p><strong>因此</strong>：若要做端到端加密，&quot;私有化部署 + fork 客户端&quot;在理论上可行，但取决于服务端可改性（需确认）；<strong>在信息不确定时，完全自建是唯一确定可行的路径</strong>。采购前还需确认其服务端是否提供端侧签名校验与密钥归属（公开资料未说明）。</p><h4 id="光靠-https-安不安全-——要看防的是什么" tabindex="-1">&quot;光靠 HTTPS 安不安全&quot;——要看防的是什么 <a class="header-anchor" href="#光靠-https-安不安全-——要看防的是什么" aria-label="Permalink to &quot;&quot;光靠 HTTPS 安不安全&quot;——要看防的是什么&quot;">​</a></h4><table tabindex="0"><thead><tr><th>威胁</th><th>后果</th><th>HTTPS + 完整性校验是否够</th><th>缓解手段</th></tr></thead><tbody><tr><td><strong>链路被劫持 / 包被替换</strong></td><td><strong>任意代码在用户手机执行</strong>（最严重）</td><td><strong>基本够</strong>：HTTPS 防链路窃取，哈希 / 签名校验防替换，再加版本矩阵约束与崩溃自动回滚兜底</td><td>自建可再加端侧签名；用其 SDK 时依赖它的校验机制（需向厂商确认）</td></tr><tr><td><strong>有人拿到 bundle 逆向业务逻辑</strong></td><td>业务逻辑与接口规则泄露，<strong>不直接危害用户</strong></td><td><strong>不够</strong>——HTTPS 只管传输，管不了对方拿到文件后做什么</td><td>Hermes 字节码化（产物非明文，变量名与结构消失）+ JS 混淆 + 剔除 Source Map；<strong>要彻底解决需做端到端加密</strong>（私有化 + fork 客户端，或完全自建）</td></tr><tr><td><strong>业务代码存放在第三方</strong>（仅托管模式）</td><td>数据边界与合规问题</td><td>不适用</td><td>私有化部署或完全自建</td></tr></tbody></table><p><strong>结论</strong>：</p><ul><li>若主要担心**&quot;包被替换导致用户执行恶意代码&quot;**——托管 + HTTPS + 完整性校验 + 灰度回滚已是可接受的水位，这也是绝大多数团队的用法；</li><li>若担心**&quot;代码被逆向&quot;或&quot;不能存放在第三方&quot;<strong>——&quot;存放第三方&quot;可由</strong>私有化部署<strong>解决；若还要</strong>端到端加密**，则需&quot;私有化 + fork 客户端&quot;（需确认服务端可改性）或<strong>完全自建</strong>（确定可行）。这是本文倾向自建的深层理由，而不仅是&quot;灰度策略要自定义&quot;这一条。</li></ul><h4 id="自建时的加解密做法-端到端加密" tabindex="-1">自建时的加解密做法（端到端加密） <a class="header-anchor" href="#自建时的加解密做法-端到端加密" aria-label="Permalink to &quot;自建时的加解密做法（端到端加密）&quot;">​</a></h4><p>采用<strong>混合加密</strong>：<strong>AES-256-GCM</strong> 加密内容（自带完整性 tag）+ <strong>RSA / ECC 私钥签名</strong>验来源。</p><p><strong>打包侧（CI）</strong>：<code>hermesc</code> 产出 <code>.hbc</code> → 每次随机生成数据密钥 DK，用 AES-256-GCM 加密为 <code>bundle.pkg</code> → 用私钥对包体 SHA-256 签名 → 包头写入 App 版本范围 / Bundle 版本 / 平台 / RN 版本 / 算法标识 / keyid → 上传 CDN 并登记版本矩阵。</p><p><strong>客户端侧（Native 层，三端各一份）</strong>：下载到临时目录 → <strong>先验签</strong>（内嵌公钥，失败即丢弃并上报）→ <strong>再解密</strong>（AES-GCM，C++ / 原生实现）→ 与元数据 SHA-256 比对 → 原子落盘到私有目录并收紧权限 → 下次冷启动加载，<code>markSuccess</code> 反触发。</p><p><strong>密钥与运维</strong>：公钥 / 证书<strong>内嵌 App 包</strong>随版本发布，私钥只存 KMS / CI 凭据、<strong>永不进仓库</strong>；<strong>轮换必须配合新二进制</strong>（公钥在包内），建议有效期 1–2 年，先发新版覆盖用户再切换密钥；客户端只接受 Bundle 版本<strong>高于当前</strong>的包，以防降级与重放。</p><p><strong>关键工程约束</strong>：解密与验签必须在 <strong>Native 层</strong>实现，密钥不得明文出现在 JS 层——因此该模块必须有原生同学参与，不能由前端同学单独完成。这段对应客户端 26–39 人天中的验签（1.5–2 / 端）、解密（2–3 / 端）、安全存储（1.5–2 / 端）。</p><h4 id="成本对比" tabindex="-1">成本对比 <a class="header-anchor" href="#成本对比" aria-label="Permalink to &quot;成本对比&quot;">​</a></h4><blockquote><p>价格为公开报价，人天为参考估算，最终以询价与实际评估为准。</p></blockquote><table tabindex="0"><thead><tr><th>路线</th><th>一次性投入</th><th>长期费用</th><th>周期</th></tr></thead><tbody><tr><td><strong>B 完全自建（从零）——【推荐】</strong></td><td><strong>60–100 人天</strong>（明细见下）</td><td>CDN 与存储按量（通常数百至数千元/月）+ <strong>0.2–0.3 人力/年运维</strong></td><td>6–10 周</td></tr><tr><td><strong>C 私有化部署（服务端自持，沿用其 SDK）</strong></td><td><strong>15–30 人天</strong></td><td>CDN 按量 + <strong>0.1–0.2 人力/年运维</strong>（服务端自维护，无厂商兜底）</td><td>3–5 周</td></tr><tr><td><strong>A 托管（Pushy SaaS）——过渡备选</strong></td><td><strong>三端接入 2–5 人天</strong></td><td><strong>¥66/月起（≈ ¥792/年）</strong>；专业版 ¥7200/年；大客户按日均查询次数 VIP1（1000 万次）<strong>¥30000/年</strong>、VIP2 ¥60000/年、VIP3 ¥120000/年</td><td><strong>1–2 周</strong></td></tr></tbody></table><h4 id="关于-客户端-26–39-人天-——为什么不是-下载后解密就行" tabindex="-1">关于&quot;客户端 26–39 人天&quot;——为什么不是&quot;下载后解密就行&quot; <a class="header-anchor" href="#关于-客户端-26–39-人天-——为什么不是-下载后解密就行" aria-label="Permalink to &quot;关于&quot;客户端 26–39 人天&quot;——为什么不是&quot;下载后解密就行&quot;&quot;">​</a></h4><p><strong>口径</strong>：26–39 人天为 <strong>iOS + Android + 鸿蒙三端合计</strong>；单端约 8–13 人天；只做 iOS / Android 两端约 17–26 人天。</p><p><strong>&quot;下载 + 解密&quot;只是其中两项。</strong> 工作量主体是<strong>失败态处理</strong>——每种异常都必须有确定行为，否则就是线上事故：下载中断、包损坏、验签失败、版本不匹配、更新后启动崩溃、磁盘不足、多进程并发、老版本回退、灰度分组漂移。</p><table tabindex="0"><thead><tr><th>工作项</th><th>iOS</th><th>Android</th><th>鸿蒙</th><th>说明</th></tr></thead><tbody><tr><td>下载器（断点续传、超时重试、并发与流量控制）</td><td>2</td><td>2</td><td>3</td><td>鸿蒙侧生态不熟需多预留</td></tr><tr><td>验签（公钥校验、防重放、时间戳）</td><td>1.5</td><td>1.5</td><td>2</td><td>公钥内嵌与轮换方案</td></tr><tr><td>解密（AES-GCM，Native 层实现 + 密钥内存保护）</td><td>2</td><td>2</td><td>3</td><td>不得在 JS 层实现</td></tr><tr><td>安全存储与原子替换（私有目录、权限、防篡改）</td><td>1.5</td><td>1.5</td><td>2</td><td></td></tr><tr><td>版本兼容校验 + 回滚 / 反触发 + 多版本保留</td><td>1.5</td><td>1.5</td><td>2</td><td>更新后崩溃自动回退</td></tr><tr><td>容器改造（指定加载 Bundle、重载、与路由衔接）</td><td>2</td><td>2</td><td>2</td><td></td></tr><tr><td>共用设计 / 契约 / 日志与可观测（三端只做一次）</td><td>—</td><td>—</td><td>—</td><td>2–3</td></tr><tr><td><strong>合计</strong></td><td></td><td></td><td></td><td><strong>约 26–39 人天</strong></td></tr></tbody></table><h4 id="自建到底要做哪些事-工时来自这些具体事项" tabindex="-1">自建到底要做哪些事（<strong>工时来自这些具体事项</strong>） <a class="header-anchor" href="#自建到底要做哪些事-工时来自这些具体事项" aria-label="Permalink to &quot;自建到底要做哪些事（**工时来自这些具体事项**）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>角色</th><th>具体工作项</th><th>一次性投入</th><th>长期投入</th></tr></thead><tbody><tr><td><strong>客户端（三端）</strong></td><td>见上表（下载器 / 验签 / 解密 / 安全存储 / 回滚 / 容器改造 / 共用设计）</td><td><strong>26–39 人天</strong></td><td>随 RN 版本升级维护</td></tr><tr><td><strong>服务端</strong></td><td>① 下发接口（按 App 版本、平台、渠道查询最新包）② 版本矩阵存储与强制校验 ③ <strong>灰度策略引擎</strong>（百分比、设备稳定分桶、渠道/人群定向）④ 发布后台（上传、审核、发布、暂停、禁用、回滚）⑤ 签名服务（私钥接入 KMS、留痕与审计）⑥ 数据统计（请求量、命中率、下载/安装成功率、失败原因分布）⑦ 打通现有账号权限体系</td><td><strong>15–25 人天</strong></td><td>功能迭代与值班支持</td></tr><tr><td><strong>运维</strong></td><td>① CDN 与对象存储（缓存、回源、预热、带宽成本）② 密钥/证书托管（KMS）与轮换流程 ③ 监控告警（下发失败率、安装成功率、<strong>按 Bundle 版本的崩溃率</strong>）④ 应急预案与回滚演练 ⑤ 值班 SOP 与权限授予</td><td><strong>5–10 人天</strong></td><td><strong>0.2–0.3 人力/年 + CDN 流量成本</strong></td></tr><tr><td><strong>安全</strong></td><td>① OTA 威胁建模与方案评估 ② 密钥管理规范与白盒保护 ③ 客户端实现评估（解密是否下沉 Native、密钥是否可提取）④ 渗透测试（中间人替换 Bundle、重放、降级攻击）⑤ 逐条核对 Apple 条款并出审核 checklist</td><td><strong>5–10 人天</strong></td><td>定期评估与密钥轮换</td></tr><tr><td><strong>测试</strong></td><td>① 热更专项用例设计与执行（弱网、中断、断电、包损坏、验签失败、版本错配、磁盘不足、回滚、灰度分桶稳定性、禁用开关即时性）② 三端一致性用例 ③ 回归范围分级标准 ④ 灰度发布演练</td><td><strong>5–8 人天</strong></td><td>每次热更包的回归</td></tr><tr><td><strong>产品 / 运营</strong></td><td>① 判断哪些需求走 OTA ② 建立&quot;可走 OTA / 必须发版&quot;的审批口径 ③ 灰度放量决策与数据观察</td><td><strong>1–2 人天</strong></td><td>每次发布的审批动作</td></tr></tbody></table><h4 id="结论-倾向自建-托管作为过渡" tabindex="-1">结论：倾向自建，托管作为过渡 <a class="header-anchor" href="#结论-倾向自建-托管作为过渡" aria-label="Permalink to &quot;结论：倾向自建，托管作为过渡&quot;">​</a></h4><p>自建理由见 <strong>1.2（共 6 条）</strong>；其中 ⑤⑥ 与本节直接相关：⑤ <strong>端到端加密在原版 SDK 上做不到</strong>：托管服务端不可控；私有化需 fork 开源客户端并确认服务端可改性；自建则完全自由、确定可行；⑥ <strong>只有自建才不存在业务代码存放在第三方的问题</strong>。</p><p><strong>兜底路径</strong>：若一期排期确实不允许 60–100 人天，可先用 Pushy 托管过渡（2–5 人天、约 ¥792/年起），后续迁移到私有化部署（路线 C，15–30 人天）或完全自建。两条路径最终都指向自建，只是节奏不同；<strong>过渡期间默认接受&quot;无端到端加密、代码存于第三方&quot;这一状态</strong>，需由团队显式确认。</p><p><strong>无论哪条路线，以下两项仍需我们自己做</strong>：密钥与证书管理规范、设备可信校验（iOS App Attest / 华为设备证书 / 安卓侧自有风控能力）。</p><h3 id="_3-5-灰度、回滚与止血" tabindex="-1">3.5 灰度、回滚与止血 <a class="header-anchor" href="#_3-5-灰度、回滚与止血" aria-label="Permalink to &quot;3.5 灰度、回滚与止血&quot;">​</a></h3><p>任何 OTA 方案必须具备以下能力，缺一项不允许上线：</p><ul><li><strong>灰度能力</strong>：百分比灰度 / 按设备 ID 稳定分桶 / 按渠道定向（且下发须受 4.2 的版本矩阵约束）；</li><li><strong>止血能力</strong>：服务端一键禁用 + 客户端自动回滚（<code>markSuccess</code> 反触发：更新后首次启动未上报成功，下次启动自动退回上一版本）；</li><li><strong>可观测与值守</strong>：采用率、下载成功率、安装成功率、<strong>按 Bundle 版本聚合的崩溃率</strong>；以及明确的紧急联系人与值班授权。</li></ul><hr><h2 id="_4-发布方式与-bundle-管理" tabindex="-1">4. 发布方式与 Bundle 管理 <a class="header-anchor" href="#_4-发布方式与-bundle-管理" aria-label="Permalink to &quot;4. 发布方式与 Bundle 管理&quot;">​</a></h2><h3 id="_4-1-三种发布形态-澄清-要不要半夜发版" tabindex="-1">4.1 三种发布形态（<strong>澄清&quot;要不要半夜发版&quot;</strong>） <a class="header-anchor" href="#_4-1-三种发布形态-澄清-要不要半夜发版" aria-label="Permalink to &quot;4.1 三种发布形态（**澄清&quot;要不要半夜发版&quot;**）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>形态</th><th>触发场景</th><th>是否需商店审核</th><th>是否需要非工作时间操作</th></tr></thead><tbody><tr><td><strong>随版本发布</strong>（常规）</td><td>常规迭代、新功能、含原生改动</td><td>需要</td><td><strong>否</strong>，与现在完全一样</td></tr><tr><td><strong>内置 Bundle 更新</strong></td><td>每次 App 发版时，包内基线 Bundle 同步更新</td><td>需要</td><td><strong>否</strong></td></tr><tr><td><strong>热更新 / 灰度下发</strong></td><td>线上问题修复、运营内容变更、小流量验证</td><td>否</td><td><strong>仅紧急修复时需要</strong>；常规热更是工作时间内的后台发布</td></tr></tbody></table><p><strong>写 RN 不需要半夜发版。</strong> OTA 是&quot;随时可发&quot;，不是&quot;必须半夜发&quot;；需要非工作时间操作的只有一种情况——线上严重问题需立即止血。而且新 Bundle 只对<strong>下一次冷启动</strong>生效，用户感知与操作时间无关。</p><p>紧急下发按此阶梯执行（建议写进值班手册）：<strong>确认影响面 → 修复出包 → 内部验证 → 灰度 5% → 观察崩溃率与业务指标 30–60 分钟 → 30% → 100%</strong>，异常时服务端一键禁用、客户端下次冷启动自动回退。</p><h3 id="_4-2-bundle-版本管理-不只是热更新才用" tabindex="-1">4.2 Bundle 版本管理（<strong>不只是热更新才用</strong>） <a class="header-anchor" href="#_4-2-bundle-版本管理-不只是热更新才用" aria-label="Permalink to &quot;4.2 Bundle 版本管理（**不只是热更新才用**）&quot;">​</a></h3><p>常见误解是&quot;Bundle 只有热更新时才变&quot;。实际<strong>每次 App 发版时，包内都要内置一份新基线 Bundle</strong>，OTA 下发的是基于该基线的补丁，二者纳入同一张版本矩阵。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>App v9.5.0（内置 Bundle B9.5.0）</span></span>
<span class="line"><span>   ├─ 热更补丁 P1（适用于 v9.5.0）</span></span>
<span class="line"><span>   ├─ 热更补丁 P2（适用于 v9.5.0，回滚目标 P1）</span></span>
<span class="line"><span>   └─ …</span></span>
<span class="line"><span>App v9.6.0（内置 Bundle B9.6.0，包含此前所有补丁的正式化）</span></span>
<span class="line"><span>   └─ 新一轮补丁…</span></span></code></pre></div><p><strong>规则</strong>：</p><ol><li>每个 App 版本内置一份基线 Bundle，作为该版本兜底（无网络也能跑）；</li><li>补丁只对其声明的 App 版本范围生效；</li><li>每次发版时把已验证的补丁<strong>固化进新的基线 Bundle</strong>，避免补丁链无限增长；</li><li>版本矩阵 <code>App 版本 × Bundle 版本 × 三端</code> 必须显式维护并由服务端强制校验——这是防止&quot;新 Bundle 打在老二进制上&quot;的唯一手段。</li></ol><h3 id="_4-3-对-git-与-jenkins-的影响-可用脚本实现-不必改造-jenkins-体系" tabindex="-1">4.3 对 Git 与 Jenkins 的影响（<strong>可用脚本实现，不必改造 Jenkins 体系</strong>） <a class="header-anchor" href="#_4-3-对-git-与-jenkins-的影响-可用脚本实现-不必改造-jenkins-体系" aria-label="Permalink to &quot;4.3 对 Git 与 Jenkins 的影响（**可用脚本实现，不必改造 Jenkins 体系**）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>影响</th></tr></thead><tbody><tr><td>分支管理</td><td><strong>基本无变化</strong>，沿用现有分支模型；RN 代码建议独立仓库（或 Monorepo 独立目录），版本打 tag 与 App 版本关联</td></tr><tr><td>Jenkins 打包</td><td><strong>新增一个构建阶段</strong>，可用脚本实现：产出 Bundle（三端各一份）→ Hermes 字节码化 → 加密 + 签名 → 上传；随后执行原有 build</td></tr><tr><td>产物管理</td><td>新增 Bundle 制品与版本矩阵记录，纳入现有制品管理</td></tr><tr><td>灰度发布</td><td>App 包仍走商店；Bundle 走下发通道（可独立于 App 版本）</td></tr></tbody></table><p>Bundle 相关每一步都是命令行可完成的，Jenkins 只需在原有流程前增加一个&quot;执行脚本&quot;步骤，脚本失败即中断构建。</p><h4 id="jenkins-脚本要做的事-事项不少-这是新增工作量来源" tabindex="-1">Jenkins 脚本要做的事（<strong>事项不少，这是新增工作量来源</strong>） <a class="header-anchor" href="#jenkins-脚本要做的事-事项不少-这是新增工作量来源" aria-label="Permalink to &quot;Jenkins 脚本要做的事（**事项不少，这是新增工作量来源**）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>#</th><th>阶段</th><th>脚本要做的事</th></tr></thead><tbody><tr><td>1</td><td>环境与前置检查</td><td>Node / 依赖版本校验；分支与 App 版本号校验；工作区干净校验；CI 凭据可用性检查</td></tr><tr><td>2</td><td>安装依赖</td><td>npm / ohpm 依赖安装与缓存复用，失败即中断</td></tr><tr><td>3</td><td><strong>构建三端 Bundle</strong></td><td>iOS、Android 各出一份；鸿蒙走 <code>bundle-harmony</code>；同时产出 assets</td></tr><tr><td>4</td><td><strong>Hermes 字节码化</strong></td><td>调用 <code>hermesc</code> 产出 <code>.hbc</code> 并校验有效性</td></tr><tr><td>5</td><td><strong>Source Map 产出与上传</strong></td><td>上传 Hermes Source Map 到崩溃平台（供 JS 堆栈还原，<strong>漏了无法补救</strong>）</td></tr><tr><td>6</td><td><strong>加密与签名</strong></td><td>从 KMS / CI 凭据取私钥签名，产出加密包与签名文件（私钥不落脚本、不进仓库）</td></tr><tr><td>7</td><td><strong>版本矩阵写入</strong></td><td>记录 App 版本 × Bundle 版本 × 平台 × 灰度通道</td></tr><tr><td>8</td><td>上传 CDN / 制品库</td><td>上传加密包并校验可正常回源下载</td></tr><tr><td>9</td><td>产物归档</td><td>Bundle 包、Source Map、构建日志归档留存，便于追溯与回滚</td></tr><tr><td>10</td><td><strong>注入内置基线 Bundle</strong></td><td>把基线 Bundle 拷入原生工程资源目录，供后续 build 打进 App 包</td></tr><tr><td>11</td><td>失败处理</td><td>任一步失败即非零退出码、打印明确错误、触发告警</td></tr><tr><td>12</td><td>（可选）触发灰度</td><td>调用发布接口设置灰度比例，或仅上传待人工放量</td></tr></tbody></table><p><strong>脚本必须满足四点</strong>：① 幂等；② 失败即非零退出码；③ 产物带 App 版本号、Bundle 版本号与校验值；④ 私钥走 CI 凭据 / KMS，<strong>不落脚本、不进仓库</strong>。</p><p><strong>脚本的本质</strong>：在原有 build 之前插入一段&quot;产出 Bundle → Hermes 字节码化 → 加密签名 → 上传 CDN → 把基线 Bundle 拷入原生工程资源目录&quot;。每一步都是命令行可完成的标准动作，因此<strong>用现有脚本方式即可承接，方案细节待选型确定后补充</strong>，不必预先固化实现。</p><hr><h2 id="_5-承载范围-哪些页面用-rn" tabindex="-1">5. 承载范围：哪些页面用 RN <a class="header-anchor" href="#_5-承载范围-哪些页面用-rn" aria-label="Permalink to &quot;5. 承载范围：哪些页面用 RN&quot;">​</a></h2><h3 id="_5-1-复用口径-保守-且可度量" tabindex="-1">5.1 复用口径（保守，且可度量） <a class="header-anchor" href="#_5-1-复用口径-保守-且可度量" aria-label="Permalink to &quot;5.1 复用口径（保守，且可度量）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层次</th><th>内容</th><th>期望复用率</th></tr></thead><tbody><tr><td>L1 逻辑层</td><td>网络、数据模型、缓存、鉴权、埋点、业务计算</td><td>90%+</td></tr><tr><td>L2 组件 / 页面层</td><td>UI 组件、业务页面、状态管理</td><td><strong>双端 70%–90%</strong></td></tr><tr><td>L3 平台适配层</td><td>TurboModules、原生桥接、平台差异分支</td><td>不复用，<strong>这层的大小决定整体上限</strong></td></tr></tbody></table><p><strong>提醒</strong>：真正成本不在&quot;写 RN 页面&quot;而在 L3——把登录、支付、会员卡、取票码、定位、推送、埋点等能力做成三端语义一致的 TurboModule，必须在评估时单独计入；鸿蒙侧还需确认每个三方依赖是否有 RNOH 适配版本。</p><h3 id="_5-2-由谁来决定-关键机制" tabindex="-1">5.2 由谁来决定（<strong>关键机制</strong>） <a class="header-anchor" href="#_5-2-由谁来决定-关键机制" aria-label="Permalink to &quot;5.2 由谁来决定（**关键机制**）&quot;">​</a></h3><p>该问题长期争议的根源是信息与责任不对称：<strong>技术知道风险边界，产品知道业务优先级</strong>，谁单独拍板都会出问题。建议采用&quot;<strong>技术出标准、产品做选择、指标兜底、争议升级</strong>&quot;：</p><table tabindex="0"><thead><tr><th>环节</th><th>负责方</th><th>产出</th></tr></thead><tbody><tr><td>① 制定《技术栈准入标准》</td><td>技术</td><td>明确&quot;哪些类型必须原生&quot;（首页、选座、支付、强手势/复杂动效、极致体验要求），其余默认 RN</td></tr><tr><td>② 具体页面选型</td><td>产品 / 业务 在标准范围内决定</td><td>页面级技术栈标注</td></tr><tr><td>③ 设立体验达标线</td><td>技术 + 产品 共同确认</td><td>可量化指标：首屏耗时、帧率、崩溃率、与原生同类的差值上限（示例口径：首屏差值 ≤ 30%、帧率不低于原生同类 90%、崩溃率不高于原生同类；<strong>具体阈值以 PoC 实测后确定</strong>）</td></tr><tr><td>④ 上线前验收</td><td>产品 + 测试</td><td>对照达标线验收，不达标则回退原生或优化</td></tr><tr><td>⑤ 争议升级</td><td>技术负责人 + 产品负责人</td><td>按&quot;达标线是否达标&quot;作为客观裁定依据</td></tr></tbody></table><p><strong>价值在于把&quot;体验不好&quot;从主观指责变成可验收指标</strong>：达标线上线前共同确认，事后争议有客观依据，不必由某一方单独背锅。</p><p><strong>按类型划分的承载范围（示例）</strong>（供讨论）：</p><table tabindex="0"><thead><tr><th>技术栈</th><th>建议模块</th></tr></thead><tbody><tr><td>保持原生</td><td>首页、核心交易链路（如选座 / 下单 / 支付）</td></tr><tr><td>优先 RN</td><td>内容资讯、评论/榜单、会员权益与积分、票券与卡包、周边商城、活动运营页</td></tr><tr><td>保持 H5</td><td>对外投放、需要外链传播的轻量活动页</td></tr></tbody></table><hr><h2 id="_6-rn-版本升级与回归成本-重点-必须写进年度排期" tabindex="-1">6. RN 版本升级与回归成本（<strong>重点：必须写进年度排期</strong>） <a class="header-anchor" href="#_6-rn-版本升级与回归成本-重点-必须写进年度排期" aria-label="Permalink to &quot;6. RN 版本升级与回归成本（**重点：必须写进年度排期**）&quot;">​</a></h2><p>这是引入 RN 后<strong>长期、周期性</strong>存在的成本，易被低估，也是测试工作量波动的主要来源。</p><h3 id="_6-1-为什么必须升——不升的代价" tabindex="-1">6.1 为什么必须升——不升的代价 <a class="header-anchor" href="#_6-1-为什么必须升——不升的代价" aria-label="Permalink to &quot;6.1 为什么必须升——不升的代价&quot;">​</a></h3><ol><li><strong>官方只维护最近 3 个次版本</strong>：落后即进入 Unsupported，Bug 修复与安全补丁不再提供，遇到 RN 自身问题只能自己改源码——成本极高且每次升级都要重复解决。</li><li><strong>工具链会被倒逼升级</strong>：Xcode、Android SDK、Gradle / AGP、Kotlin 要求随 RN 抬高，商店也会提高最低 SDK 门槛。拖得越久越可能被迫一次跨多版本（RN 0.82 移除旧架构即为典型强制切换），风险与工作量成倍放大。</li><li><strong>三方库逐步不再支持旧版本</strong>，出问题无人修复。</li><li><strong>安全</strong>：Unsupported 版本出现 CVE 不会回溯修复。</li></ol><h3 id="_6-2-为什么升级需要大范围回归——影响面说明" tabindex="-1">6.2 为什么升级需要大范围回归——影响面说明 <a class="header-anchor" href="#_6-2-为什么升级需要大范围回归——影响面说明" aria-label="Permalink to &quot;6.2 为什么升级需要大范围回归——影响面说明&quot;">​</a></h3><p><strong>RN 升级替换的是整个运行时</strong>（Hermes、Fabric、TurboModules、Codegen），<strong>不是升级某个 SDK</strong>；所有 RN 页面都跑在同一运行时之上，因此：</p><blockquote><p><strong>理论上所有 RN 页面都在影响范围内，不存在&quot;只影响某一个页面&quot;。</strong></p></blockquote><table tabindex="0"><thead><tr><th>风险类型</th><th>具体表现</th></tr></thead><tbody><tr><td>渲染与交互差异</td><td>布局、字体、行高、圆角阴影、安全区、图片缩放；手势、滚动惯性、返回键/侧滑、焦点与键盘行为</td></tr><tr><td>三方库与桥接接口变更</td><td>组件属性、回调、默认值变化导致隐性失效；TurboModule / Codegen 契约变化</td></tr><tr><td>动画与性能漂移</td><td>动画中断、掉帧、Reanimated 兼容；启动耗时、内存、列表帧率变化</td></tr><tr><td>三端不一致</td><td>同一份代码在 iOS / Android / 鸿蒙表现分化</td></tr></tbody></table><p><strong>每次 RN 升级都伴随一次&quot;全量 RN 页面&quot;级别的回归测试——这是引入 RN 后的常态化测试成本，必须在项目与年度排期中明确预留。</strong></p><h3 id="_6-3-建议节奏与单次成本" tabindex="-1">6.3 建议节奏与单次成本 <a class="header-anchor" href="#_6-3-建议节奏与单次成本" aria-label="Permalink to &quot;6.3 建议节奏与单次成本&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>建议</th></tr></thead><tbody><tr><td>升级节奏</td><td><strong>每 4–6 个月一次</strong>（对齐季度排期）；不必跟 RN 每 2 个月的版本，但<strong>不要跨 3 个以上版本跳跃</strong></td></tr><tr><td>跨 3+ 版本升级</td><td>视为专项项目：独立排期、更重的回归与更长的灰度观察</td></tr><tr><td>单次成本（估算）</td><td>升级改造 <strong>3–8 人天</strong> + 回归测试 <strong>5–15 人天</strong>（视 RN 页面数量，首年取下限）</td></tr><tr><td>年度占用</td><td>约 2 次 × (8–23) 人天 ≈ <strong>16–46 人天/年</strong>（RN 页面规模扩大后上行）</td></tr></tbody></table><p><strong>每次升级要做的事（工时即由此构成）</strong>：</p><table tabindex="0"><thead><tr><th>#</th><th>步骤</th><th>具体内容</th><th>人天</th></tr></thead><tbody><tr><td>1</td><td>升级前评估</td><td>阅读变更日志与破坏性变更清单；核对三方库兼容版本；确认 RNOH 是否有对应版本</td><td>1–2</td></tr><tr><td>2</td><td>升级改造</td><td>依赖升级、Codegen 契约适配、废弃 API 替换、三端工程配置（Gradle / Pod / CMake）调整</td><td>2–6</td></tr><tr><td>3</td><td>自动化冒烟</td><td>跑核心页 E2E；对比性能基线（启动耗时、内存、帧率）</td><td>1–2</td></tr><tr><td>4</td><td><strong>人工回归（大头）</strong></td><td>L1 全量、L2 冒烟 + 关键路径、L3 冒烟；<strong>三端各执行一遍</strong></td><td><strong>5–15</strong></td></tr><tr><td>5</td><td>灰度观察</td><td>随版本灰度发布，观察崩溃率与业务指标后全量</td><td>1–2（可与发版合并）</td></tr></tbody></table><h3 id="_6-4-如何压降回归成本-纪律问题-不是技术问题" tabindex="-1">6.4 如何压降回归成本（<strong>纪律问题，不是技术问题</strong>） <a class="header-anchor" href="#_6-4-如何压降回归成本-纪律问题-不是技术问题" aria-label="Permalink to &quot;6.4 如何压降回归成本（**纪律问题，不是技术问题**）&quot;">​</a></h3><ol><li><strong>禁止改动 RN 源码、禁止深度定制</strong>——定制越多升级越痛，这是所有手段里最重要的一条。</li><li><strong>组件集中化</strong>：样式与交互收敛进业务组件库，升级时只改一处。</li><li><strong>平台差异收敛进适配层</strong>，禁止散落业务代码。</li><li><strong>分级回归</strong>：L1 核心页（高频、含权益/券/支付）全量；L2 冒烟 + 关键路径；L3 冒烟。</li><li><strong>自动化冒烟</strong>：核心页建 E2E 脚本，升级后先跑自动化再人工，把人工回归压到 L1。</li><li><strong>固定升级窗口</strong>：每季度预留排期，避免临时插入打乱业务迭代。</li></ol><hr><h2 id="_7-对现有团队与流程的影响" tabindex="-1">7. 对现有团队与流程的影响 <a class="header-anchor" href="#_7-对现有团队与流程的影响" aria-label="Permalink to &quot;7. 对现有团队与流程的影响&quot;">​</a></h2><h3 id="_7-1-native-同学需要掌握什么-现学现用路径" tabindex="-1">7.1 Native 同学需要掌握什么（现学现用路径） <a class="header-anchor" href="#_7-1-native-同学需要掌握什么-现学现用路径" aria-label="Permalink to &quot;7.1 Native 同学需要掌握什么（现学现用路径）&quot;">​</a></h3><blockquote><p>前提：本项目由现有原生同学承担。</p></blockquote><table tabindex="0"><thead><tr><th>领域</th><th>需要掌握</th><th>上手方式</th></tr></thead><tbody><tr><td><strong>TypeScript / React 基础</strong></td><td>类型、组件、Hooks、状态管理</td><td>官方 React 文档 + 内部 2 周集中学习</td></tr><tr><td><strong>RN 特有概念</strong></td><td>布局（Flexbox）、样式、生命周期、平台差异</td><td>官方 RN 文档 Guides</td></tr><tr><td><strong>原生桥接（原生同学的优势项）</strong></td><td>TurboModules + Codegen 写契约并生成三端绑定</td><td>官方 Native Modules 文档；<strong>上手最快，建议作为切入点</strong></td></tr><tr><td><strong>构建与调试</strong></td><td>Metro、Fast Refresh、DevTools、三端运行</td><td>官方 Environment Setup</td></tr><tr><td><strong>性能与包体</strong></td><td>长列表、动画线程、Bundle 体积</td><td>Reanimated / FlashList 官方示例</td></tr><tr><td><strong>热更新与安全</strong></td><td>下发流程、加解密、验签、灰度回滚</td><td>内部文档 + 平台组带教</td></tr></tbody></table><p><strong>上手建议</strong>：从&quot;把一个低频二级页面用 RN 重写&quot;开始，同时承担 1–2 个 TurboModule 桥接——后者是原生同学强项，能快速产出价值。<strong>要求全员掌握基础，每人能独立完成 RN 页面开发与桥接调用。</strong></p><h3 id="_7-2-开发工具与日常编码方式" tabindex="-1">7.2 开发工具与日常编码方式 <a class="header-anchor" href="#_7-2-开发工具与日常编码方式" aria-label="Permalink to &quot;7.2 开发工具与日常编码方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>编码</td><td>TypeScript + React 函数式组件 + Hooks</td></tr><tr><td>IDE</td><td>VS Code（RN 开发）/ Xcode、Android Studio、DevEco Studio（原生与三端运行）</td></tr><tr><td>调试</td><td>Fast Refresh 秒级热重载；React Native DevTools；原生断点在各自 IDE</td></tr><tr><td>运行</td><td>iOS/Android 用 RN CLI 起 Metro 连真机/模拟器；鸿蒙用 DevEco Studio + <code>bundle-harmony</code></td></tr><tr><td>三端差异</td><td>按平台后缀区分代码，差异收敛进统一适配层</td></tr><tr><td>与原生联调</td><td>原生容器提供入口参数（路由、用户态、埋点上下文）；RN 通过 TurboModule 调用原生能力</td></tr></tbody></table><h3 id="_7-3-对测试的影响" tabindex="-1">7.3 对测试的影响 <a class="header-anchor" href="#_7-3-对测试的影响" aria-label="Permalink to &quot;7.3 对测试的影响&quot;">​</a></h3><ol><li><strong>三端验证</strong>：同一份 RN 代码需在三端分别验证（平台差异、字体、手势、返回键/侧滑需逐端看）。</li><li><strong>热更新专项</strong>（全新测试类型）：用例清单见 3.4 测试角色工作项，涵盖弱网中断降级、版本错配拒绝加载、验签解密失败兜底、更新后崩溃自动回滚、灰度分桶稳定性、禁用开关即时性。</li><li><strong>回归范围</strong>：RN 运行时升级或公共组件改动时分级回归（核心页全量、其余冒烟）；日常单页改动只回归该页。</li><li><strong>对产品/业务</strong>：需求描述需标注技术栈（走 RN 还是原生，影响排期与上线方式）；需适应&quot;先灰度看数据再全量&quot;的节奏；埋点口径必须与原生页面统一，否则数据割裂。</li></ol><hr><h2 id="_8-落地前需要先建好的基础能力" tabindex="-1">8. 落地前需要先建好的基础能力 <a class="header-anchor" href="#_8-落地前需要先建好的基础能力" aria-label="Permalink to &quot;8. 落地前需要先建好的基础能力&quot;">​</a></h2><h3 id="_8-1-网络、埋点、登录等-框架层-复用还是自研" tabindex="-1">8.1 网络、埋点、登录等&quot;框架层&quot;：复用还是自研？ <a class="header-anchor" href="#_8-1-网络、埋点、登录等-框架层-复用还是自研" aria-label="Permalink to &quot;8.1 网络、埋点、登录等&quot;框架层&quot;：复用还是自研？&quot;">​</a></h3><p><strong>结论：能复用原生通道的一律复用。</strong> 在 RN 里重写一套会直接带来数据割裂（埋点口径不一致、登录态不同步）与双份维护成本。</p><table tabindex="0"><thead><tr><th>能力</th><th>建议方案</th><th>理由</th></tr></thead><tbody><tr><td><strong>埋点</strong></td><td><strong>复用现有原生埋点 SDK</strong>，通过 TurboModule 暴露给 RN</td><td>埋点口径必须与原生页面完全一致，否则数据分析不可用</td></tr><tr><td><strong>登录态 / 鉴权</strong></td><td><strong>复用原生</strong>，RN 只读取</td><td>涉及安全，不应有两套实现</td></tr><tr><td><strong>网络请求</strong></td><td>与现有网关强绑定（统一签名、加解密、风控头）的能力走 <strong>TurboModule 复用原生通道</strong>；简单业务接口可用 RN 侧 HTTP 库</td><td>涉及统一网关协议与签名的必须复用</td></tr><tr><td><strong>路由 / 跳转</strong></td><td>统一路由表，RN 与原生互跳走同一套 scheme</td><td>避免两套路由各自维护</td></tr><tr><td><strong>日志 / 配置 / 推送</strong></td><td>复用原生</td><td>同上</td></tr></tbody></table><p><strong>成本</strong>：复用方案的成本主要是写 TurboModule 桥接（每个能力约 1–3 人天，含三端）；自研除开发成本外，还要长期维护两套逻辑与两套埋点口径，<strong>长期成本更高、风险更大</strong>。因此<strong>复用更优</strong>。</p><p><strong>必须新建的</strong>只有&quot;RN 侧薄封装层&quot;：定义 TS 契约 → Codegen 生成三端绑定 → 三端各写实现 → RN 侧包装统一 API 与类型 → 统一错误码与超时/重试 → 补埋点与日志。整体约 5–10 人天。</p><h3 id="_8-2-ui-组件-需要一套-但不要从零写-且必须按设计稿重做视觉" tabindex="-1">8.2 UI 组件：需要一套，但不要从零写（<strong>且必须按设计稿重做视觉</strong>） <a class="header-anchor" href="#_8-2-ui-组件-需要一套-但不要从零写-且必须按设计稿重做视觉" aria-label="Permalink to &quot;8.2 UI 组件：需要一套，但不要从零写（**且必须按设计稿重做视觉**）&quot;">​</a></h3><p>与页面强绑定的控件（标签页、下拉刷新、空状态、Toast、弹窗、导航栏等）<strong>必须在 RN 侧有一套</strong>，因为 RN 页面无法直接使用原生 UI 组件。</p><p><strong>要区分&quot;能力&quot;与&quot;视觉&quot;</strong>：社区库解决的是<strong>能力</strong>（能否下拉刷新、能否切页、动画是否跑在 UI 线程），<strong>不带我们的设计稿视觉</strong>；间距、字号、圆角、颜色、动效曲线都必须按App 设计规范重新定义。因此成本上<strong>视觉对齐与封装占大头（约 60%–70%）</strong>，能力接入是小头。</p><table tabindex="0"><thead><tr><th>场景</th><th>做法</th><th>视觉处理</th></tr></thead><tbody><tr><td>标签页 / 页面切换</td><td>基于成熟社区方案（如 react-native-tab-view / pager-view）</td><td>按设计稿重做指示器、选中态、滑动阈值</td></tr><tr><td>下拉刷新 / 长列表</td><td>RN 自带 RefreshControl + FlashList（长列表性能必需）</td><td>刷新动画与文案按规范替换</td></tr><tr><td>手势与动画</td><td>Reanimated + Gesture Handler（动画跑 UI 线程）</td><td>动效曲线统一到设计令牌</td></tr><tr><td>复杂自绘（座位图、票面、海报）</td><td>Skia</td><td>完全按设计稿绘制</td></tr><tr><td>Toast / 弹窗 / 空状态 / 加载 / 导航栏</td><td>基于基础组件自行封装</td><td>逐一按设计稿实现</td></tr></tbody></table><p><strong>统一做法</strong>：先建立<strong>设计令牌（Design Token）</strong>——间距、字号、字重、圆角、颜色、动效曲线集中定义，组件只引用令牌。规范调整时只改令牌；这也是 RN 版本升级时降低回归成本的关键（见 6.4）。</p><p><strong>要做的事</strong>：梳理设计规范并落成令牌 → 选定底层社区方案 → 按设计稿实现视觉 → 三端核对渲染差异 → 补无障碍与埋点 → 写文档与示例页。</p><p><strong>成本</strong>：组件库（常用 15–25 个组件）约 <strong>15–25 人天</strong>，其中视觉实现约 10–17 人天。这部分<strong>必须做</strong>，否则每页重复造轮子，视觉与质量都无法统一。</p><p><strong>另一项必备的工程约束</strong>：建立 <strong>Bundle 体积预算</strong>——每次构建产出体积报告，超限阻断；长列表与动画的实现方式已在表中明确（核心列表页的卡顿基本都出在长列表）。</p><hr><h2 id="_9-线上监控" tabindex="-1">9. 线上监控 <a class="header-anchor" href="#_9-线上监控" aria-label="Permalink to &quot;9. 线上监控&quot;">​</a></h2><table tabindex="0"><thead><tr><th>监控对象</th><th>建议方案</th></tr></thead><tbody><tr><td><strong>原生层崩溃 / ANR</strong></td><td>沿用现有崩溃监控平台（以 Bugly 为例）（自 2024-05 起支持鸿蒙，三端可统一）</td></tr><tr><td><strong>RN / JS 层异常</strong></td><td>Bugly 专业版（腾讯端服务 TDS）<strong>2025-10 起支持 React Native 监控</strong>（错误监控、页面访问、自定义上报）；另有 <code>bugly-rn-sdk</code>（腾讯云可观测平台，当前 beta / 灰度）。<strong>选型前需与腾讯侧确认套餐与稳定性</strong></td></tr><tr><td><strong>Hermes 字节码堆栈还原</strong></td><td><strong>必做且须提前确认</strong>：字节码下 JS 崩溃只有偏移，需上传 Hermes Source Map 才能还原到源码行。<strong>先向厂商确认是否支持</strong>，不支持则换方案。这是&quot;上线首日必须打通、事后补不回来&quot;的工程项</td></tr><tr><td><strong>Bundle 版本维度</strong></td><td>崩溃率、ANR、首屏耗时必须能按 <strong>Bundle 版本（updateId）+ App 版本 + 端</strong>下钻——<strong>没有这个维度，热更新就无法安全运行</strong>（无法判断某个补丁是否劣化）</td></tr></tbody></table><p><strong>成本（Bugly 专业版，腾讯端服务 TDS）</strong>：预付费资源包，两种套餐（刊例价，元/年）——</p><table tabindex="0"><thead><tr><th>套餐</th><th>档位</th><th>价格</th></tr></thead><tbody><tr><td><strong>事件量套餐</strong>（按上报量，无采样率限制）</td><td>6 亿条/年（参考 MAU 20w）</td><td>32,000</td></tr><tr><td></td><td>15 亿条/年（参考 MAU 50w）</td><td>80,000</td></tr><tr><td></td><td>30 亿条/年（参考 MAU 100w）</td><td>160,000</td></tr><tr><td><strong>月活套餐</strong>（按 MAU 阶梯，无采样率限制）</td><td>5 万</td><td>50,000</td></tr><tr><td></td><td>10 万</td><td>80,000</td></tr><tr><td></td><td>20 万</td><td>130,000</td></tr><tr><td></td><td>50 万</td><td>240,000</td></tr><tr><td></td><td>100 万</td><td>350,000</td></tr></tbody></table><p>有效期 365 天，按天统计、次日结算。<strong>RN 监控为专业版功能，免费版 Bugly（bugly.qq.com）的基础崩溃监控免费但不含</strong>；选型时按自身 MAU 对照档位即可。<code>bugly-rn-sdk</code>（腾讯云可观测平台）目前为 beta / 灰度，<strong>计费与稳定性未公开，暂不作为报价依据，需另行向腾讯确认</strong>。<strong>这是监控侧一笔真实的新增成本，应与 OTA 建设成本分开列出</strong>，避免被误认为&quot;RN 监控不花钱&quot;。</p><hr><h2 id="_10-风险与应对" tabindex="-1">10. 风险与应对 <a class="header-anchor" href="#_10-风险与应对" aria-label="Permalink to &quot;10. 风险与应对&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>风险</th><th>应对</th></tr></thead><tbody><tr><td>R1</td><td><strong>鸿蒙侧 RN 版本线滞后，当前 RNOH 主线（0.84）官方已 Unsupported</strong></td><td>落地前向华为/SIG 确认 0.86 线时间表；三端统一版本；把&quot;升到 Active&quot;列为首季度硬任务</td></tr><tr><td>R2</td><td><strong>落后即失去补丁支持，且升级需全量 RN 页面回归、测试成本周期性上升</strong></td><td>每 4–6 个月升一次；不跨 3 个以上版本；禁止改动 RN 源码；核心页自动化冒烟。<strong>详见第 6 章</strong></td></tr><tr><td>R3</td><td><strong>三方库鸿蒙适配缺口，可能推高工作量</strong></td><td>落地前完成依赖清单逐项盘点；优先选已适配版本；为自适配预留预算</td></tr><tr><td>R4</td><td>热更触碰合规红线导致审核被拒</td><td>3.2 节红线写入规范；发布前合规 checklist</td></tr><tr><td>R5</td><td>Bundle 与二进制版本不匹配导致大规模崩溃</td><td>版本矩阵强制校验；灰度 5% 起步；自动回滚；服务端一键禁用</td></tr><tr><td>R6</td><td>密钥/加解密实现不当被提取</td><td>实现下沉 Native；密钥走 KMS + 白盒；定期轮换（公钥内嵌包内，轮换需配合新二进制）</td></tr></tbody></table><hr><h2 id="附-参考来源-公开资料" tabindex="-1">附：参考来源（公开资料） <a class="header-anchor" href="#附-参考来源-公开资料" aria-label="Permalink to &quot;附：参考来源（公开资料）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>来源</th><th>用于支撑本文的哪部分</th></tr></thead><tbody><tr><td>[1]</td><td><a href="https://reactnative.dev/releases/overview" target="_blank" rel="noreferrer">React Native 官方《Releases Overview》</a></td><td>版本支持策略与 2026 年现状（Active / End of Cycle / Unsupported）</td></tr><tr><td>[2]</td><td><a href="https://reactnative.dev/blog" target="_blank" rel="noreferrer">React Native 官方博客（0.84 / 0.87 发布说明）</a></td><td>Hermes V1 默认、新架构、构建工具链要求</td></tr><tr><td>[3]</td><td><a href="https://openharmonycrossplatform.csdn.net/6a9fcdd5790f037e6e39a174.html" target="_blank" rel="noreferrer">OpenHarmony SIG <code>ohos_react_native</code>（RNOH）及社区解读</a></td><td>鸿蒙侧版本线、架构、三方库适配数量</td></tr><tr><td>[4]</td><td><a href="https://pushy.reactnative.cn/docs/intro" target="_blank" rel="noreferrer">Pushy 热更新（React Native 中文网）官网与文档</a></td><td>三端覆盖、增量差分实测、核心代码开源、¥66/月起定价</td></tr><tr><td>[5]</td><td><a href="https://bugly.tds.qq.com/docs/news/changes/" target="_blank" rel="noreferrer">Bugly 专业版新功能发布记录（2025-10 / 2026-03）</a></td><td>RN / JS 层监控的支持情况</td></tr><tr><td>[6]</td><td><a href="https://www.tencentcloud.com/zh/document/product/248/79941" target="_blank" rel="noreferrer">腾讯云可观测平台 React Native SDK 文档</a></td><td><code>bugly-rn-sdk</code> 集成方式与当前灰度状态</td></tr><tr><td>[7]</td><td><a href="https://developer.apple.com/forums/thread/73856" target="_blank" rel="noreferrer">Apple Developer Forums（JSPatch 警告，2017-03）</a></td><td>热更新合规边界（配合审核指南与开发者协议条款引述）</td></tr><tr><td>[8]</td><td><a href="https://engineering.fb.com/2019/07/12/android/hermes/" target="_blank" rel="noreferrer">Meta Engineering《Hermes》</a></td><td>Hermes 字节码预编译与性能设计目标</td></tr><tr><td>[9]</td><td><a href="https://bugly.tds.qq.com/docs/billing" target="_blank" rel="noreferrer">Bugly 专业版《产品计费》</a></td><td>专业版报价与两种套餐的计费方式</td></tr></tbody></table>`,169)])])}const b=r(e,[["render",s]]);export{p as __pageData,b as default};
